// ===== NANO: СДВИГ СРАБАТЫВАЕТ С ПЕРВОГО РАЗА =====
//
// ВАРИАНТ 1: Arduino Nano + аккумулятор 3S (11,1 В) + лампа 12 В
// Загрузка: Инструменты -> Плата -> Arduino Nano,
//          Процессор -> ATmega328P (Old Bootloader) для китайских копий.
//
// Датчик сдвига и магнита с лампой
// Компас GY-273 + MOSFET-модуль + лампа
//
// Как работает:
//   * После включения питания 2 минуты ждём (светодиод на плате мигает),
//     чтобы успеть поставить датчик на место. Потом 3 раза мигнёт светодиод на плате:
//     охрана включена.
//   * СДВИГ  — предмет повернули или наклонили (срабатывает С ПЕРВОГО раза)
//              -> лампа горит постоянно ALARM_SECONDS секунд.
//              (версия «сразу»: MOVES_NEEDED = 1)
//   * МАГНИТ — рядом поднесли или убрали магнит -> лампа мигает.
//   * Если IDLE_DAYS дней подряд не было ни одной тревоги, лампа загорается сама.
//   * Между проверками плата спит, чтобы батарейка служила дольше.
//
// Подключение:
//   Питание +  -> RAW (Pro Mini) или VIN (Nano)  и MOSFET DC+
//   Питание -  -> GND                             и MOSFET DC-
//   GY-273:  VCC -> VCC (Pro Mini) или 5V (Nano),  GND -> GND,  SDA -> A4,  SCL -> A5
//   MOSFET:  Signal PWM+ -> D9,  Signal GND -> GND
//            клеммы «Controlled device» -> лампа (плюс лампы к «+»)
//
// Программа сама определяет чип на GY-273 (QMC5883L или HMC5883L).
// Дополнительные библиотеки ставить не нужно.

#include <Wire.h>
#include <avr/sleep.h>
#include <avr/wdt.h>
#include <avr/interrupt.h>

// ===== Настройки (их можно менять) =====
const int  LAMP_PIN            = 9;    // контакт, к которому подключён MOSFET-модуль
const int  LED_PIN             = 13;   // светодиод на плате
const int  WAIT_SECONDS        = 15;  // через сколько секунд после включения начинается охрана
const long MOVE_THRESHOLD      = 50;   // чувствительность к сдвигу (меньше = чувствительнее)
const long MAGNET_THRESHOLD    = 50;   // чувствительность к магниту (меньше = чувствительнее)
const int  ALARM_SECONDS       = 2;    // сколько секунд звучит сирена при тревоге
const int  MOVES_NEEDED        = 1;    // со скольких сдвигов включается тревога
const int  MOVE_WINDOW_SECONDS = 60;   // за сколько секунд должны случиться эти сдвиги
const unsigned long IDLE_DAYS  = 5;    // через сколько дней тишины лампа загорится сама
const int  IDLE_LAMP_SECONDS   = 2;    // сколько секунд звучит сирена в этом случае
                                       // (0 = гореть, пока не отключат питание)
const bool DEBUG               = true// true = показывать числа в мониторе порта
// =======================================

const unsigned long DAY_MS = 86400000UL;

const byte QMC_ADDR = 0x0D;
const byte HMC_ADDR = 0x1E;
byte chip = 0;                      // 1 = QMC5883L, 2 = HMC5883L

long baseX, baseY, baseZ;           // направление поля в спокойном состояни
long baseStrength;                  // сила поля в спокойном состоянии

int moveCount = 0;                  // сколько сдвигов уже замечено
unsigned long firstMoveTime = 0;    // когда был первый из них
unsigned long lastEventTime = 0;    // когда была последняя тревога (или включение охраны)

// ---------- Часы, которые идут и во сне ----------
// Во сне обычные часы Arduino (millis) стоят, поэтому время считаем
// по «будильнику» (сторожевому таймеру), который тикает примерно 4 раза в секунду.
volatile unsigned long wdtTicks = 0;
float tickMs = 250.0;               // длина одного тика, уточняется измерением
unsigned long clockBaseMs = 0, clockBaseTicks = 0, lastCalibration = 0;

ISR(WDT_vect) { wdtTicks++; }

unsigned long ticksNow() {
  noInterrupts();
  unsigned long t = wdtTicks;
  interrupts();
  return t;
}

unsigned long nowMs() {
  return clockBaseMs + (unsigned long)((ticksNow() - clockBaseTicks) * tickMs);
}

void startTicker() {
  cli();
  MCUSR &= ~(1 << WDRF);
  WDTCSR = (1 << WDCE) | (1 << WDE);
  WDTCSR = (1 << WDIE) | (1 << WDP2);  // прерывание примерно каждые 0,25 с, без перезагрузки
  sei();
}

// Будильник неточный, поэтому меряем его длину по кварцу платы
void calibrateClock() {
  unsigned long t0 = ticksNow();
  while (ticksNow() == t0) delay(1);    // ждём начала тика
  unsigned long start = micros();
  unsigned long t1 = ticksNow();
  while (ticksNow() - t1 < 8) delay(1); // меряем 8 тиков
  float measured = (micros() - start) / 8000.0;

  clockBaseMs = nowMs();
  clockBaseTicks = ticksNow();
  tickMs = measured;
  lastCalibration = clockBaseMs;
}

// Короткий сон до следующего тика
void sleepTick() {
  if (DEBUG) Serial.flush();
  set_sleep_mode(SLEEP_MODE_PWR_DOWN);
  cli();
  sleep_enable();
  sei();
  sleep_cpu();
  sleep_disable();
}

// ---------- Основная программа ----------
void setup() {
  if (DEBUG) Serial.begin(9600);
  pinMode(LAMP_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LAMP_PIN, LOW);
  ADCSRA = 0;                         // выключаем ненужный узел платы, экономим заряд

  startTicker();

  Wire.begin();
  detectChip();

  if (chip == 0) {
    // Компас не найден: быстро мигаем светодиодом без остановки
    while (true) {
      digitalWrite(LED_PIN, HIGH); delay(100);
      digitalWrite(LED_PIN, LOW);  delay(100);
    }
  }
  if (DEBUG) Serial.println(chip == 1 ? "Найден чип QMC5883L" : "Найден чип HMC5883L");

  calibrateClock();

  // Время, чтобы поставить датчик на место (светодиод мигает)
  for (int i = 0; i < WAIT_SECONDS; i++) {
    digitalWrite(LED_PIN, HIGH); delay(100);
    digitalWrite(LED_PIN, LOW);  delay(900);
  }

  rememberCalmState();
  lastEventTime = nowMs();
  armedSignal(); // охрана включена: 3 раза мигает светодиод на плате (сирена молчит)
  if (DEBUG) Serial.println("Охрана включена");
}

void loop() {
  sleepTick();                        // спим примерно четверть секунды

  unsigned long now = nowMs();

  // Раз в 6 часов уточняем длину тика будильника
  if (now - lastCalibration > 6UL * 3600UL * 1000UL) calibrateClock();

  // Пять дней тишины: лампа загорается сама
  if (now - lastEventTime >= IDLE_DAYS * DAY_MS) {
    idleLamp();
    return;
  }

  long x, y, z;
  readAverage(x, y, z, chip == 1 ? 2 : 1);

  long magnetChange = labs(strength(x, y, z) - baseStrength);           // сила поля
  long moveChange = labs(x - baseX) + labs(y - baseY) + labs(z - baseZ); // направление поля

  if (DEBUG) {
    Serial.print("Сдвиг: ");
    Serial.print(moveChange);
    Serial.print("   Магнит: ");
    Serial.println(magnetChange);
  }

  // Если второй сдвиг не случился вовремя, начинаем счёт заново
  if (moveCount > 0 && now - firstMoveTime > MOVE_WINDOW_SECONDS * 1000UL) {
    moveCount = 0;
    digitalWrite(LED_PIN, LOW);
  }

  if (magnetChange > MAGNET_THRESHOLD) {
    magnetAlarm();             // магнит включает тревогу сразу
  } else if (moveChange > MOVE_THRESHOLD) {
    moveCount++;
    if (moveCount == 1) firstMoveTime = now;

    if (moveCount >= MOVES_NEEDED) {
      moveAlarm();             // второй сдвиг: включаем лампу
    } else {
      digitalWrite(LED_PIN, HIGH); // первый сдвиг: только запоминаем
      delay(2000);                 // ждём, пока предмет успокоится
      rememberCalmState();
    }
  }
}

// ---------- Тревоги ----------

// Сдвиг: лампа горит постоянно
void moveAlarm() {
  if (DEBUG) Serial.println("ТРЕВОГА: СДВИГ!");
  digitalWrite(LED_PIN, HIGH);
  digitalWrite(LAMP_PIN, HIGH);
  delay(ALARM_SECONDS * 1000UL);
  digitalWrite(LAMP_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
  afterAlarm();
}

// Магнит: лампа мигает
void magnetAlarm() {
  if (DEBUG) Serial.println("ТРЕВОГА: МАГНИТ!");
  for (int i = 0; i < ALARM_SECONDS * 5 / 3; i++) {
    digitalWrite(LED_PIN, HIGH);
    digitalWrite(LAMP_PIN, HIGH);
    delay(300);
    digitalWrite(LED_PIN, LOW);
    digitalWrite(LAMP_PIN, LOW);
    delay(300);
  }
  afterAlarm();
}

// Долго ничего не происходило: лампа загорается сама
void idleLamp() {
  if (DEBUG) Serial.println("Долго не было тревог: включаю лампу");
  digitalWrite(LAMP_PIN, HIGH);
  if (IDLE_LAMP_SECONDS == 0) {
    while (true) sleepTick();  // лампа горит, пока не отключат питание
  }
  delay(IDLE_LAMP_SECONDS * 1000UL);
  digitalWrite(LAMP_PIN, LOW);
  afterAlarm();                // и снова отсчитываем дни
}

// После тревоги ждём и запоминаем новое спокойное состояние
void afterAlarm() {
  moveCount = 0;
  delay(3000);
  rememberCalmState();
  lastEventTime = nowMs();
  if (DEBUG) Serial.println("Снова на охране");
}

// Сигнал «охрана включена»: только светодиод на плате, без сирены
void armedSignal() {
  for (int i = 0; i < 3; i++) {
    digitalWrite(LED_PIN, HIGH); delay(150);
    digitalWrite(LED_PIN, LOW);  delay(150);
  }
}

void rememberCalmState() {
  readAverage(baseX, baseY, baseZ, chip == 1 ? 30 : 10);
  baseStrength = strength(baseX, baseY, baseZ);
}

// Сила поля (длина вектора)
long strength(long x, long y, long z) {
  return (long)sqrt((double)x * x + (double)y * y + (double)z * z);
}

// ---------- Работа с компасом ----------
bool chipAnswers(byte addr) {
  Wire.beginTransmission(addr);
  return Wire.endTransmission() == 0;
}

void writeReg(byte addr, byte reg, byte value) {
  Wire.beginTransmission(addr);
  Wire.write(reg);
  Wire.write(value);
  Wire.endTransmission();
}

void detectChip() {
  if (chipAnswers(QMC_ADDR)) {
    chip = 1;
    writeReg(QMC_ADDR, 0x0B, 0x01); // рекомендованная настройка
    writeReg(QMC_ADDR, 0x09, 0x15); // непрерывное измерение, 50 Гц, диапазон 8 Гс
  } else if (chipAnswers(HMC_ADDR)) {
    chip = 2;
    writeReg(HMC_ADDR, 0x00, 0x70); // усреднение 8 замеров, 15 Гц
    writeReg(HMC_ADDR, 0x01, 0x20); // диапазон 1,3 Гс
    writeReg(HMC_ADDR, 0x02, 0x00); // непрерывное измерение
  }
  delay(100);
}

// Читает 6 байт подряд из компаса
void readBytes(byte addr, byte reg, byte *buf) {
  Wire.beginTransmission(addr);
  Wire.write(reg);
  Wire.endTransmission();
  Wire.requestFrom(addr, (byte)6);
  for (int i = 0; i < 6; i++) {
    buf[i] = Wire.available() ? Wire.read() : 0;
  }
}

// Одно измерение. Результат примерно в миллигауссах для обоих чипов.
void readOnce(long &x, long &y, long &z) {
  byte b[6];
  if (chip == 1) {
    readBytes(QMC_ADDR, 0x00, b);                         // порядок: X, Y, Z (младший байт первым)
    int16_t rx = (int16_t)(b[0] | (b[1] << 8));
    int16_t ry = (int16_t)(b[2] | (b[3] << 8));
    int16_t rz = (int16_t)(b[4] | (b[5] << 8));
    x = rx / 3; y = ry / 3; z = rz / 3;                   // 3000 единиц = 1 Гс
  } else {
    readBytes(HMC_ADDR, 0x03, b);                         // порядок: X, Z, Y (старший байт первым)
    int16_t rx = (int16_t)((b[0] << 8) | b[1]);
    int16_t rz = (int16_t)((b[2] << 8) | b[3]);
    int16_t ry = (int16_t)((b[4] << 8) | b[5]);
    x = rx * 10L / 11; y = ry * 10L / 11; z = rz * 10L / 11; // 1090 единиц = 1 Гс
  }
}

// Среднее из нескольких измерений, чтобы убрать дрожание чисел
void readAverage(long &x, long &y, long &z, int count) {
  long sx = 0, sy = 0, sz = 0;
  for (int i = 0; i < count; i++) {
    long a, b, c;
    readOnce(a, b, c);
    sx += a; sy += b; sz += c;
    if (i < count - 1) delay(chip == 1 ? 20 : 70);
  }
  x = sx / count; y = sy / count; z = sz / count;
}
